{
  "decisions": [
    {
      "requirement_id": "ETC-101",
      "methods": [
        "Test"
      ],
      "rationale": "The behavior is verified by sending a trackside text message with no defined start sub-conditions and observing that the OBU immediately treats the start condition as fulfilled."
    },
    {
      "requirement_id": "ETC-102",
      "methods": [
        "Test"
      ],
      "rationale": "The OBU's handling of driver acknowledgement for text messages is verified by simulating driver inputs and observing the display termination logic under different message configurations."
    },
    {
      "requirement_id": "ETC-103",
      "methods": [
        "Test"
      ],
      "rationale": "The requirement is verified by setting up a scenario where the end condition is already met when the start condition is fulfilled and confirming that the message is not displayed."
    },
    {
      "requirement_id": "ETC-104",
      "methods": [
        "Test"
      ],
      "rationale": "The measurement of display length based on the start location is verified by moving the train through specific locations and observing the text display duration and position."
    },
    {
      "requirement_id": "ETC-105",
      "methods": [
        "Test"
      ],
      "rationale": "The transmission of the driver acknowledgement report is verified by acknowledging a message and monitoring the communication channel to the RBC for the correct report content."
    },
    {
      "requirement_id": "ETC-106",
      "methods": [
        "Test"
      ],
      "rationale": "The rejection logic is verified by sending a new text message with a duplicate identifier while the previous one is unacknowledged and observing the OBU's rejection response."
    },
    {
      "requirement_id": "ETC-107",
      "methods": [
        "Test"
      ],
      "rationale": "The deletion logic for Mode Profiles upon receiving an infill MA is verified by simulating infill scenarios and inspecting the resulting Mode Profile state in the OBU."
    },
    {
      "requirement_id": "ETC-108",
      "methods": [
        "Test"
      ],
      "rationale": "The treatment of the Mode Profile start as a temporary EOA and the calculation of the temporary SvL are verified by driving the train towards the profile start and observing the speed supervision behavior."
    },
    {
      "requirement_id": "ETC-109",
      "methods": [
        "Test"
      ],
      "rationale": "The replacement of stored LX information is verified by sending two LX messages with the same identity and checking that the OBU retains the data from the second message."
    }
  ]
}

