      "covers": [
        "KDH-039"
      ],
      "type": "Sınır",
      "priority": "Yüksek",
      "preconditions": "A company representative account exists with an active authenticator. The failed-attempt threshold is N (as defined in VBP SDD §14).",
      "test_inputs": "Invalid credentials for the authenticator.",
