        },
        {
          "no": 3,
          "action": "Attempt to authenticate using the disabled authenticator.",
          "expected": "Authentication fails. The system requires re-binding."
        },
        {
          "no": 4,
          "action": "Re-bind the authenticator to the account.",
          "expected": "Re-binding succeeds."
        },
        {
          "no": 5,
          "action": "Attempt to authenticate using the re-bound authenticator with valid credentials.",
